using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class IgnazioSilone
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'uomo non esiste veramente che nella lotta contro i propri limiti.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'operaio di una città moderna usufruisce, oggi, di un benessere materiale superiore a quello di un nobile dei secoli scorsi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La lotta finale sarà fra comunisti ed ex comunisti.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Qualcosa di esso rimane e lascia la sua impronta sul carattere, che uno si porta dietro per tutta la vita. È interessante notare come gli ex comunisti siano facilmente riconoscibili. Formano una categoria a sé, come un tempo i preti e gli ufficiali dopo aver lasciato i loro ruoli.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "A chi guarda Fontamara da lontano, dal Feudo del Fucino, l'abitato sembra un gregge di pecore scure e il campanile un pastore. Un villaggio insomma come tanti altri; ma per chi vi nasce e cresce, il cosmo. L'intera storia universale vi si svolge: nascite morti amori odii invidie lotte disperazioni.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "I giovani non conoscono la storia, ma noi vecchi la conosciamo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "In capo a tutti c'è Dio, padrone del cielo. Questo ognuno lo sa. Poi viene il principe Torlonia, padrone della terra. Poi vengono le guardie del principe. Poi vengono i cani delle guardie del principe. Poi, nulla. Poi, ancora nulla. Poi, ancora nulla. Poi vengono i cafoni. E si può dire ch'è finito.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Un cittadino ed un cafone difficilmente possono capirsi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Un pezzo di carta in famiglia può sempre servire.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Per capir bene le parole sacre bisogna trovarsi in stato d'innocenza; anche allora però esse possono rimanere misteriose.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La storie invecchiano solo per quelli che non ci pensano.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Il mondo è rotondo. Chi parte, perde tempo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "I mutamenti accaduti con la guerra portarono anche in quella remota valle sorprese e illusioni; ma, per finire, piovve e nevicò come gli altri anni, e i poveri rimasero poveri.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Nei giorni di miseria, anche il brodo d'un osso può nutrire.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La sicurezza è sempre relativa; anche la Pubblica Sicurezza non farebbe male a chiamarsi Pubblico Pericolo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ah, com'è miserabile un'intelligenza che non serve che a fabbricare alibi per far tacere la coscienza.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Si vive nel provvisorio. Si pensa che per ora la vita va male, per ora bisogna arrangiarsi, per ora bisogna anche umiliarsi, ma che tutto ciò è provvisorio. La vera vita comincerà un giorno. Ci prepariamo a morire col rimpianto di non aver vissuto. A volte quest'idea mi ossessiona: si vive una sola volta e quest'unica volta si vive nel provvisorio, nella vana attesa del giorno in cui dovrebbe cominciare la vera vita. Così passa l'esistenza.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La libertà non è una cosa che si possa ricevere in regalo. Si può vivere anche in paese di dittatura ed essere libero, a una semplice condizione, basta lottare contro la dittatura. L'uomo che pensa con la propria testa e conserva il suo cuore incorrotto, è libero. L'uomo che lotta per ciò che egli ritiene giusto, è libero. Per contro, si può vivere nel paese più democratico della terra, ma se si è interiormente pigri, ottusi, servili, non si è liberi; malgrado l'assenza di ogni coercizione violenta, si è schiavi. Questo è il male, non bisogna implorare la propria libertà dagli altri. La libertà bisogna prendersela, ognuno la porzione che può.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'asino è ancora fortunato. Un asino di solito lavora fino a ventiquattro anni, un mulo fino a ventidue, un cavallo fino a quindici. Ma l'uomo disgraziato lavora fino a settanta e più. Perché Dio ha avuto pietà degli animali e non dell'uomo? D'altronde, Lui ha il diritto di fare quello che gli pare.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'invidia qui è nell'aria.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Abbandonò la Chiesa non perché si fosse ricreduto sulla validità dei suoi dogmi e l'efficacia dei sacramenti, ma perché gli parve che essa s'identificasse con la società corrotta, meschina e crudele che avrebbe dovuto invece combattere.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Carne avvezza a soffrire, dolore non sente.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ho l'impressione che i tempi diventeranno sempre più duri e che solo uomini di quella sorta sopravviveranno. Per la ragione detta ora da lei: è carne avvezza a soffrire.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Arriva sempre un'età in cui i giovani trovano insipido il pane e il vino della propria casa. Essi cercano altrove il loro nutrimento. Il pane e il vino delle osterie che si trovano nei crocicchi delle grandi strade, possono solo calmare la loro fame e la loro sete. Ma l'uomo non può vivere tutta la sua vita nelle osterie", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "In ogni dittatura un solo uomo, anche un piccolo uomo qualsiasi, il quale continui a pensare con la propria testa, mette in pericolo l'ordine pubblico. Tonnellate di carta stampata propagano le parole d'ordine del regime; migliaia di altoparlanti, centinaia di migliaia di manifesti e di fogli volanti distribuiti gratuitamente, schiere di oratori su tutte le piazze e i crocicchi, migliaia di preti dal pergamo ripetono fino all'ossessione fino all'istupidimento collettivo, quelle parole d'ordine. Ma basta che un piccolo uomo, un solo piccolo uomo dica NO, e quel formidabile ordine granitico è in pericolo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La forza della dittatura è nei muscoli, non nel cuore.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Il destino è un'invenzione della gente fiacca e rassegnata.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non c'è mortorio senza scherzi, né matrimonio senza pianti.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'uomo di Dio deve essere sempre stanco. Nell'ozio vengono i pensieri inutili, e dietro ad essi, il Maligno sempre in agguato.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "In ogni tempo e in qualunque società l'atto supremo dell'anima è di darsi, di perdersi per trovarsi. Si ha solo quello che si dona.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Cara Cristina, non bisogna essere ossessionati dall'idea di sicurezza, neppure della sicurezza delle proprie virtù: Vita spirituale e vita sicura, non stanno assieme. Per salvarsi bisogna rischiare.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ogni idea nuova per propagarsi, si cristallizza in formule; per conservarsi si affida a un corpo di interpreti, prudentemente reclutato, talvolta anche appositamente stipendiato, e, a ogni buon conto, sottoposto a un'autorità superiore, incaricata di sciogliere i dubbi e di reprimere le deviazioni. Così ogni nuova idea finisce sempre col diventare una idea fissa, immobile, sorpassata. Quando questa idea diventa dottrina ufficiale dello Stato, allora non c'è più scampo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Per fare bene il socialista bisogna essere milionario.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Poeta si diventa, ma vedova di guerra si nasce.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Se ne vede tanta di carta e di carta gratuita e piena di bugie, che fa perfino ribrezzo di doversene servire per la propria pulizia.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "A ogni uomo che ama la pulizia, un foglio di carta può sempre servire.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Gli uomini i quali una volta dicevano no alla società e andavano nei conventi, adesso il più sovente finiscono tra i fautori della rivoluzione sociale. Non esito ad attribuire ai ribelli il merito di una più vicina fedeltà a Cristo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Lo vedi? Quando mai per le opere di misericordia c'è voluto un permesso speciale?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Per condannare gli innocenti, quelli che hanno il potere trovano sempre qualche legge. Sono essi che le fanno, le leggi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "L'ospitalità è un'opera di misericordia.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non vi sono padroni né servi nella casa del Padre, ma solo figli eguali e liberi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Purtroppo la veste da prete non ispira fiducia.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Avete detto di aver celebrato poco fa la Santa Messa? E con tale sveltezza vi trasformate in sbirro?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Voi preti ci fate rimpiangere Nerone e Diocleziano. Essere perseguitati da quei nemici dichiarati di Cristo doveva essere meno doloroso.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La croce di Cristo, se non sbaglio, era di legno, come pure lo sono la maggior parte dei crocifissi. Non so se voi pensate che per questo essi siano privi di dignità.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Credete che se Cristo fosse andato in giro per la Palestina con la mitra o il triregno sulla testa, sarebbe stato più dignitoso?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Strana idea vi siete fatti della dignità cristiana voi preti.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "È scandaloso che un cristiano ponga l'ubbidienza prima della verità. Se, ad esempio, il capo della Chiesa predica l'odio e benedice le armi, cioè il contrario di quello che Cristo ha insegnato, i cristiani devono continuare a ubbidirgli?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Il dovere di disubbidire ai superiori che tradiscono è sacrosanto, è il più cristiano dei doveri. La coscienza è al di sopra dell'ubbidienza.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ma come si può rifiutare un principio giusto solo per timore delle conseguenze?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Le sue parole furono tradite con l'appoggio del papa e dei vescovi. Nel concetto francescano della povertà essi vedevano un pericolo per i loro privilegi e quelli delle loro famiglie.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Perché dovrebbe essere concesso ai frati e ai preti quello che Cristo non permise agli apostoli?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Perché no? Un modo di vivere assieme, secondo la carità e non secondo le leggi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "A udire questi due nomi, San Benedetto, San Francesco, uno sente piegarsi le ginocchia. I fondatori sono di solito delle aquile, i seguaci delle galline. Sì, è vero, in ogni grande agglomerazione è inevitabile una certa tendenza al pollaio.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "È difficile che un buon cristiano possa estraniarsi dalla sorte dei suoi simili. Il fratello maggiore non può disinteressarsi dei fratelli minori. Anche Cristo andò nel deserto, ma per un tempo limitato.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Cristo promise ai suoi: Quando vi troverete insieme, sarò con voi. Non disse: Quando sarete soli, o quando sarete lontani dal mondo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Nella loro maggioranza, gli uomini non sono in grado di seguire il vostro esempio spregiudicato e audace. Eppure anche le creature più deboli hanno diritto alla salvezza. Cristo è morto anche per loro.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Se voi aveste la bontà di spiegarci cosa intendete per coscienza pulita, magnifico signore, è probabile che dareste un contributo originale alla storia dell'umorismo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Scusate, a parte il resto, non si è mai visto che due persone riescano a imprigionarne quattro.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "No, non abbiate paura, è una semplice equazione aritmetica.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ha confessato? Ma un uomo di legge come voi, signor baglivo, sa meglio di me che cosa un giudice esperto riesce a far dire a un imputato in catene.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La speranza degli infelici rinasce sempre.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Anche i cardinali, fra Ludovico, voglio dire, se preferisci, perfino i cardinali sono creature di Dio, a lui soggette.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Però Cristo non dimostrò mai il minimo interesse verso di loro.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non so se ricordi quando nelle litanie dei santi aggiungevamo: dalla curia romana libera nos Domine.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Guarda se nella folla ci sia qualcuno che porta ancora pollastri, cacicavalli, prosciutti per i monsignori dell'ufficio delle suppliche.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ai supplicanti daranno l'indirizzo di casa.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Il cristianesimo infatti non è un modo di dire, ma un modo di vivere. E non si può decentemente predicare il cristianesimo agli altri, se non si vive da cristiani.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Fate il bene gratuitamente e non raccontatelo a nessuno. Tanto più che Dio in ogni caso vi vede e vi ricompenserà. Ma anche se Dio non vi badasse anche allora fare il bene è una buona cosa.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Se sono io che devo decidere, preferirei sapere chi ha dalla sua parte la verità.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Strano, veramente strano. Non immaginavo che potesse esistere un uomo come voi, assolutamente refrattario al senso del potere. Ne sono assai preoccupato. È difficoltà grave che, già nel prossimo avvenire, potrà avere conseguenze disastrose per la Chiesa.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Santa Maria della Vittoria? Di quale vittoria si rende onore alla Madre di Cristo?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Si riferisce certamente a quella di Carlo d'Angiò su Corradino di Svevia.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La Madre di Cristo ha preso parte alla battaglia? È stata vista dalla parte dei francesi?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non certo dalla Madre di Cristo.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "D'altra parte, nessuno Stato sarebbe in grado di mantenere l'ordine pubblico se i sudditi cessassero di nutrire un sacro terrore dell'inferno, e questa funzione spetta ovviamente alla Chiesa.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Sarebbe un orribile sacrilegio. Col segno della Croce e i nomi della Trinità, si può benedire il pane, la minestra, l'olio, l'acqua, il vino, se volete anche gli strumenti da lavoro ma non le armi. Se avete un assoluto bisogno di un rito propiziatorio, cercatevi qualcuno che lo faccia in nome di Satana.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Perché non ci opponemmo con maggiore energia alla sua accettazione del pontificato? È stato un delitto irreparabile sacrificare un cristiano come lui in questo ambiente miserabile di ambiziosi, d'intriganti e di canaglie.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "In parole povere far papa un uomo pio e disinteressato che non rubasse e lasciasse rubare quelli che, per tradizione di famiglia, per così dire, vi avevano diritto.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ma se considerate sul serio la povertà una condizione favorevole alla salute dell'anima, perché non rinunziate alle vostre ricchezze? L'anima non è il bene supremo?", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La dominazione assoluta sta disgustando dal cristianesimo gli spiriti meglio disposti.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ero veramente stupido. Servirsi del potere? Che perniciosa illusione. È il potere che si serve di noi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non puoi chiedere al cavallo di volare: se non vola, non gliene puoi far torto.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La tentazione del potere è la più diabolica che possa essere tesa all'uomo, se Satana osò proporla perfino a Cristo. Con Lui non ci riuscì, ma riesce con i suoi vicari.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Ogni tanto qualcuno lo riscoprirà e accetterà con animo sereno di andare allo sbaraglio.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non lasciate avvelenare il vostro cuore dall'odio verso i falsi cristiani che ci perseguitano. Quei disgraziati che fanno commercio di Cristo, meritano soltanto la nostra pietà. Malgrado l'oro che essi ammucchiano, sono dei poveretti da commiserare. Malgrado le armi, la servitù in livrea, le vesti di seta, il cerimoniale faraonico di cui si attorniano, quelli di essi che vi trovano piacere, sono degli incoscienti, gli altri, degli infelici.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Santa ingenuità. Tu non sai che la parola anima fa sorridere chi non pensa che al potere.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non abbiamo alcun impegno d'onore verso lo Stato che voi rappresentate.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Non temiamo quelli che hanno il potere di offenderci nel corpo; ma quelli che distruggono l'anima.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "V'è ancora un terzo prepotente che lo ricerca e lo vuole solo per sé.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Penso che da bambino pure voi ne avete sentito parlare, Domine Iddio.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "I miracoli, un papa dovrebbe saperlo, li compie unicamente Domine Iddio. Se l'Altissimo, quando gli pare, si serve dell'intercessione di Pier Celestino piuttosto che di quella di Bonifazio, è chiaro che se ne assume anche la responsabilità. Bonifazio dovrebbe sapere dunque presso chi lagnarsi.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "La radice di tutti i mali, per la Chiesa, è nella tentazione del potere.", Author = "Ignazio Silone" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ignazio_Silone", Text = "Santità, se voi vi affacciate a quella finestra, vedrete sulla scalinata della cattedrale una vecchietta cenciosa, una mendicante, un essere di nessun conto nella vita di questo mondo, che sta lì dalla mattina alla sera. Ma tra un milione di anni, o tra mille milioni di anni, la sua anima esisterà ancora, perché Dio l'ha creata immortale. Mentre il regno di Napoli, quello di Francia, quello d'Inghilterra, tutti gli altri regni, con i loro eserciti, i loro tribunali, le loro fanfare e il resto, saranno tornati nel nulla.", Author = "Ignazio Silone" },
        };
    }
}